changeSet.sql:
-- =========================================================================
-- DELETE : 9 ALWAYS_ON Immigration FR à supprimer
-- =========================================================================

DELETE FROM decision_tool_visibility_rules
WHERE legal_domain = 'DROIT_IMMIGRATION' AND country = 'FRANCE' AND layer = 'ALWAYS_ON' AND tool_id IN (
    'F-IM-09-aes-metiers-tension',
    'F-IM-09-aes-famille',
    'F-IM-09-aes-humanitaire',
    'F-IM-09-aes-etudiant',
    'F-IM-11-changement-statut',
    'F-IM-12-asile-avance',
    'F-IM-13-naturalisation',
    'F-IM-19-mineurs',
    'F-IM-20-mesures-eloignement'
);

